// Prépare les 5 adaptations d'un article à partir de son contenu extrait.
// Chaque format contient un brouillon de base et un prompt prêt pour un nœud LLM (Claude/GPT).
// Rien n'est publié : tout part en file d'attente pour relecture.
const article = $('Nouvel article (RSS)').first().json;
const html = String($input.first().json.data ?? '');
const texte = html.replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
const sousTitres = [...html.matchAll(/<h[23][^>]*>([\s\S]*?)<\/h[23]>/gi)]
  .map((m) => m[1].replace(/<[^>]+>/g, '').trim()).filter(Boolean).slice(0, 5);
const phrases = texte.split(/(?<=[.!?])\s+/).filter((p) => p.length > 40);
const pointsCles = sousTitres.length ? sousTitres : phrases.slice(0, 3);
const titre = article.title ?? '';
const lien = article.link ?? '';
const source = `Titre : ${titre}\nPoints clés : ${pointsCles.join(' | ')}\nConclusion : ${phrases.at(-1) ?? ''}`;

const formats = {
  linkedin: { consigne: 'Post LinkedIn : accroche, corps en 3 points, appel à l’action.',
    brouillon: `${titre}\n\n${pointsCles.map((p) => `→ ${p}`).join('\n')}\n\nL’article complet : ${lien}` },
  thread: { consigne: 'Thread court de 4 messages maximum.',
    brouillon: pointsCles.map((p, i) => `${i + 1}/ ${p}`).join('\n') },
  newsletter: { consigne: 'Bloc newsletter : titre, 3 phrases, lien.',
    brouillon: `${titre}\n${phrases.slice(0, 3).join(' ')}\nLire : ${lien}` },
  scriptVideo: { consigne: 'Script vidéo courte (30-45 s) : accroche, 3 idées, conclusion.',
    brouillon: `Accroche : ${titre}\n${pointsCles.map((p) => `- ${p}`).join('\n')}` },
  resumeEmail: { consigne: 'Résumé email de 5 lignes maximum.',
    brouillon: phrases.slice(0, 2).join(' ') },
};
return Object.entries(formats).map(([format, f]) => ({ json: {
  format, titre, lien, brouillon: f.brouillon,
  promptIA: `${f.consigne} Utilise uniquement les informations ci-dessous, sans en ajouter.\n${source}`,
} }));

// Applique les consignes de ton de la marque à chaque format.
// Les consignes sont à remplacer par la charte éditoriale réelle de l'entreprise.
const CHARTE = {
  ton: 'clair, direct, sans jargon',
  tutoiement: false,
  motsInterdits: ['révolutionnaire', 'incroyable', 'game changer'],
};
const jours = { linkedin: 1, thread: 2, newsletter: 3, scriptVideo: 5, resumeEmail: 7 };
return $input.all().map(({ json }) => {
  const alertes = CHARTE.motsInterdits.filter((m) => json.brouillon.toLowerCase().includes(m));
  const date = new Date(Date.now() + (jours[json.format] ?? 1) * 864e5).toISOString().slice(0, 10);
  return { json: {
    ...json,
    promptIA: `${json.promptIA}\nTon : ${CHARTE.ton}. ${CHARTE.tutoiement ? 'Tutoiement.' : 'Vouvoiement.'} Mots interdits : ${CHARTE.motsInterdits.join(', ')}.`,
    alertesTon: alertes.join(', '),
    datePublicationSuggeree: date,
    statut: 'À relire',
  } };
});
